
/**
 * Generates Site component and page indexes for Agent usage.
 */

import {
    existsSync,
    readdirSync,
    writeFileSync,
} from 'node:fs';

import path from 'node:path';
import url from 'node:url';

import { readJson, consoleColors } from '../utils/helper.ts';
import { loadSite } from '../site/load-site.ts';

import type {
    SiteContext,
    PageManifest,
    ComponentManifest,
    IndexConfig,
    IndexData,
    IndexEntry,
} from '../utils/types.ts';


const {
    GREEN,
    RESET
} = consoleColors;

const GENERATED_NOTICE =
    'Automatically generated by build script. Do not edit manually.';


/**
 * Builds index data by scanning the specified Site source directory.
 */
function buildIndex(config: IndexConfig): IndexData {
    const entries: IndexEntry[] = [];

    if (existsSync(config.sourceDir)) {
        const directories = readdirSync(config.sourceDir, {
            withFileTypes: true,
        }).filter((entry) => entry.isDirectory());

        for (const entry of directories) {
            const manifestPath = path.join(
                config.sourceDir,
                entry.name,
                'manifest.json'
            );

            // Page index
            if (config.type === 'page') {
                const manifest = readJson<PageManifest>(manifestPath);

                if (!manifest || typeof manifest !== 'object') {
                    continue;
                }

                if (manifest.name && manifest.name !== entry.name) {
                    console.warn(
                        `[WKF] ${config.type} "${entry.name}" manifest name is "${manifest.name}". Index uses the directory name.`
                    );
                }

                const seo = manifest.seo ?? {};

                entries.push({
                    name: entry.name,

                    title:
                        typeof seo.title === 'string' && seo.title.trim()
                            ? seo.title.trim()
                            : entry.name,

                    description:
                        typeof seo.description === 'string'
                            ? seo.description.trim()
                            : '',

                    type: 'page',

                    output:
                        typeof manifest.output === 'string' && manifest.output.trim()
                            ? manifest.output.trim()
                            : `${entry.name}.html`,
                });

                continue;
            }

            // Component index
            const manifest = readJson<ComponentManifest>(manifestPath);

            if (!manifest || typeof manifest !== 'object') {
                continue;
            }

            if (manifest.name && manifest.name !== entry.name) {
                console.warn(
                    `[WKF] ${config.type} "${entry.name}" manifest name is "${manifest.name}". Index uses the directory name.`
                );
            }

            entries.push({
                name: entry.name,

                description:
                    typeof manifest.description === 'string'
                        ? manifest.description.trim()
                        : '',

                type: 'component',
            });
        }
    }

    entries.sort((a, b) => a.name.localeCompare(b.name));

    const key = config.type === 'component'
        ? 'components'
        : 'pages';

    return {
        _meta: {
            generated: true,
            notice: GENERATED_NOTICE,
        },
        [key]: entries,
    };
}


/**
 * Writes the generated index to the Site root directory.
 */
function writeIndex(
    site: SiteContext,
    config: IndexConfig
): IndexData {
    const index = buildIndex(config);

    const outFile = path.join(
        site.root,
        config.outputFile
    );

    writeFileSync(
        outFile,
        `${JSON.stringify(index, null, 2)}\n`,
        'utf8'
    );

    const key = config.type === 'component'
        ? 'components'
        : 'pages';

    const list = index[key];
    const count = Array.isArray(list) ? list.length : 0;

    console.log(
        `${GREEN}[WKF] wrote ${count} ${config.type}s to ${path.relative(site.root, outFile)}${RESET}`
    );

    return index;
}


/**
 * Generates all configured indexes for the selected Site.
 */
export function generateIndexes(site: SiteContext) {
    const configs: IndexConfig[] = [
        {
            type: 'component',
            sourceDir: site.paths.components,
            outputFile: 'component-index.json',
        },
        {
            type: 'page',
            sourceDir: site.paths.pages,
            outputFile: 'page-index.json',
        },
    ];

    return configs.map((config) => writeIndex(site, config));
}


// Automatically execute if run directly
const currentFilePath = url.fileURLToPath(import.meta.url);

const invokedFilePath = process.argv[1]
    ? path.resolve(process.argv[1])
    : '';

if (
    currentFilePath === invokedFilePath ||
    invokedFilePath.endsWith('generate-index.ts')
) {
    try {
        const projectRoot = process.cwd();
        const siteTitle = process.env.SITE || 'default-site';

        const siteRoot = path.resolve(
            projectRoot,
            'sites',
            siteTitle
        );

        const site = loadSite(siteRoot);

        generateIndexes(site);

    } catch (error) {
        console.error(
            '[WKF] Error generating indexes:',
            error
        );

        process.exitCode = 1;
    }
}
